stageCss:
#stage .rl-scene{ position:relative; width:100%; height:100%; display:flex; flex-direction:column; gap:14px; }

/* ============================== TOP STRIP ============================== */
#stage .rl-top{
  height:78px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 22px; border-radius:20px; white-space:nowrap;
  background:rgba(20,27,43,.78); border:1.5px solid var(--border);
}
#stage .rl-mark{
  width:46px; height:46px; border-radius:13px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.14); border:1.5px solid rgba(58,160,255,.42); color:var(--accent-1);
}
#stage .rl-mark svg{ width:25px; height:25px; }
#stage .rl-app{
  color:var(--text-primary); font-family:var(--font-mono); font-size:21px; font-weight:600;
  overflow:hidden; text-overflow:ellipsis; min-width:0;
}
#stage .rl-lat{ margin-left:auto; flex-shrink:0; display:flex; align-items:baseline; gap:8px; }
#stage .rl-lat b{
  color:#fff; font-family:var(--font-mono); font-size:26px; font-weight:700;
  font-variant-numeric:tabular-nums; transition:color .3s ease;
}
#stage .rl-lat.ok b{ color:var(--success); }
#stage .rl-lat.bad b{ color:var(--danger); }
#stage .rl-lat i{ color:var(--text-dim); font-size:18px; font-weight:600; font-style:normal; }
#stage .rl-health{
  flex-shrink:0; display:flex; align-items:center; gap:8px; padding:7px 14px; border-radius:100px;
  border:1.5px solid rgba(244,74,106,.55); background:rgba(244,74,106,.12);
  transition:border-color .3s ease, background .3s ease;
}
#stage .rl-health i{
  width:10px; height:10px; border-radius:50%; background:var(--danger);
  box-shadow:0 0 12px var(--danger); animation:msd-breathe 2s ease-in-out infinite;
}
#stage .rl-health b{ color:var(--danger); font-family:var(--font-mono); font-size:18px; font-weight:700; }
#stage .rl-health.warn{ border-color:rgba(240,166,74,.55); background:rgba(240,166,74,.12); }
#stage .rl-health.warn i{ background:var(--warn); box-shadow:0 0 12px var(--warn); }
#stage .rl-health.warn b{ color:var(--warn); }
#stage .rl-health.ok{ border-color:rgba(63,185,80,.45); background:rgba(63,185,80,.1); }
#stage .rl-health.ok i{ background:var(--success); box-shadow:0 0 12px var(--success); }
#stage .rl-health.ok b{ color:var(--success); }

/* ============================= SCENE STACK ============================= */
#stage .rl-body{ position:relative; flex:1; min-height:0; }
#stage .rl-sc{
  position:absolute; inset:0; opacity:0; transform:scale(.986); pointer-events:none;
  transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}
#stage .rl-sc.on{ opacity:1; transform:none; }
#stage .rl-sc.whip{ animation:rl-whip .44s cubic-bezier(.19,1,.22,1); }

#stage .rl-wall, #stage .rl-relay{ display:flex; flex-direction:column; gap:14px; height:100%; }

/* ------------------------------------------------------------ end nodes -- */
#stage .rl-node{
  height:132px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:24px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .rl-node.tight{ height:120px; }
#stage .rl-node.cloud{ border-color:rgba(58,160,255,.42); }
#stage .rl-node.prem{ border-color:rgba(139,149,167,.35); }
#stage .rl-node.lit{ box-shadow:0 0 0 1px rgba(58,160,255,.22), 0 0 46px rgba(58,160,255,.14); }
#stage .rl-node.ok{ border-color:rgba(63,185,80,.55); box-shadow:0 0 0 1px rgba(63,185,80,.2), 0 0 44px rgba(63,185,80,.12); }
#stage .rl-node.bad{
  border-color:rgba(244,74,106,.6); box-shadow:0 0 0 1px rgba(244,74,106,.22), 0 0 46px rgba(244,74,106,.16);
  animation:rl-alert 1s ease-in-out infinite;
}
#stage .rl-node-ic{
  width:58px; height:58px; border-radius:16px; flex-shrink:0; font-size:28px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg,#26344e,#1a2338); border:1.5px solid var(--border);
}
#stage .rl-node-t{ display:flex; flex-direction:column; gap:6px; min-width:0; }
#stage .rl-node-t b{ color:#fff; font-size:25px; font-weight:800; letter-spacing:-.3px; white-space:nowrap; }
#stage .rl-node-t i{ color:var(--text-dim); font-family:var(--font-mono); font-size:18px; font-weight:600; font-style:normal; white-space:nowrap; }
#stage .rl-node-b{
  margin-left:auto; flex-shrink:0; padding:9px 17px; border-radius:100px; white-space:nowrap;
  border:1.5px solid var(--border); background:rgba(14,20,32,.7); color:var(--text-dim);
  font-family:var(--font-mono); font-size:18px; font-weight:700; letter-spacing:1.2px;
  transition:border-color .3s ease, background .3s ease, color .3s ease;
}
#stage .rl-node-b.ok{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.14); color:var(--success); }
#stage .rl-node-b.bad{ border-color:rgba(244,74,106,.6); background:rgba(244,74,106,.16); color:var(--danger); }
#stage .rl-node-b.hot{ border-color:rgba(58,160,255,.55); background:rgba(58,160,255,.14); color:var(--accent-1); }

/* ------------------------------------------------------------- firewall -- */
#stage .rl-fw{ position:relative; flex:1; min-height:0; display:flex; align-items:center; }
#stage .rl-band{
  position:relative; z-index:2; width:100%; height:76px; border-radius:16px;
  display:flex; align-items:center; gap:16px; padding:0 22px;
  border:2px solid rgba(244,74,106,.55);
  background:
    repeating-linear-gradient(90deg, rgba(244,74,106,.16) 0 46px, transparent 46px 50px),
    repeating-linear-gradient(0deg, rgba(244,74,106,.16) 0 22px, transparent 22px 26px),
    rgba(20,27,43,.9);
  transition:border-color .3s ease, background .3s ease;
}
#stage .rl-band.ok{
  border-color:rgba(63,185,80,.5);
  background:
    repeating-linear-gradient(90deg, rgba(63,185,80,.12) 0 46px, transparent 46px 50px),
    repeating-linear-gradient(0deg, rgba(63,185,80,.12) 0 22px, transparent 22px 26px),
    rgba(20,27,43,.9);
}
#stage .rl-band-t{ color:#fff; font-family:var(--font-mono); font-size:21px; font-weight:700; white-space:nowrap; }
#stage .rl-band-b{
  margin-left:auto; padding:7px 16px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(244,74,106,.6); background:rgba(244,74,106,.18); color:var(--danger);
  font-family:var(--font-mono); font-size:17px; font-weight:800; letter-spacing:1.4px;
}
#stage .rl-band-b.ok{ border-color:rgba(63,185,80,.55); background:rgba(63,185,80,.16); color:var(--success); }

/* Two arrows through the same wall: one refused, one that was always allowed. */
#stage .rl-arrow{
  position:absolute; left:50%; top:0; bottom:0; transform:translateX(-50%);
  display:flex; flex-direction:column; align-items:center; justify-content:center; gap:10px;
  opacity:0; transition:opacity .3s ease;
}
/* The path the packet would take, so the wall has something to interrupt. */
#stage .rl-arrow::before{
  content:""; position:absolute; top:4px; bottom:4px; width:2px; z-index:0;
  background:repeating-linear-gradient(180deg, rgba(139,149,167,.4) 0 9px, transparent 9px 18px);
}
#stage .rl-arrow.on{ opacity:1; }
#stage .rl-arrow i{
  position:relative; z-index:1; display:block; width:7px; height:30px; border-radius:4px;
  background:var(--accent-1); box-shadow:0 0 14px rgba(58,160,255,.6);
}
#stage .rl-arrow.down i{ animation:rl-down 1.2s linear infinite; }
#stage .rl-arrow.down i:nth-child(2){ animation-delay:.25s; }
#stage .rl-arrow.down i:nth-child(3){ animation-delay:.5s; }
#stage .rl-arrow.up i{ background:var(--success); box-shadow:0 0 12px rgba(63,185,80,.55); animation:rl-up 1.2s linear infinite; }
#stage .rl-arrow.up i:nth-child(2){ animation-delay:.25s; }
#stage .rl-arrow.up i:nth-child(3){ animation-delay:.5s; }
#stage .rl-arrow.blocked i{ background:var(--danger); box-shadow:0 0 12px rgba(244,74,106,.55); animation:none; opacity:.55; }
#stage .rl-arrow b{
  position:absolute; z-index:5; width:52px; height:52px; border-radius:50%;
  display:none; align-items:center; justify-content:center;
  background:#2a0d16; border:2px solid var(--danger); color:var(--danger);
  font-size:22px; font-weight:800;
}
#stage .rl-arrow.blocked b{ display:flex; animation:msd-punch .4s cubic-bezier(.22,1,.36,1); }

/* ------------------------------------------------------------ the asks --- */
#stage .rl-asks{ height:104px; flex-shrink:0; display:flex; align-items:center; gap:11px; }
#stage .rl-ask{
  flex:1; min-width:0; text-align:center; padding:16px 8px; border-radius:16px; white-space:nowrap;
  overflow:hidden; text-overflow:ellipsis;
  background:rgba(14,20,32,.7); border:1.5px solid var(--border); color:var(--text-dim);
  font-family:var(--font-mono); font-size:18px; font-weight:600;
  transition:border-color .3s ease, color .3s ease, background .3s ease;
}
#stage .rl-ask.no{
  border-color:rgba(244,74,106,.5); background:rgba(244,74,106,.1); color:var(--danger);
  text-decoration:line-through; text-decoration-thickness:2px;
}

#stage .rl-alt, #stage .rl-note{
  height:96px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 20px; border-radius:20px;
  background:rgba(20,27,43,.5); border:1.5px dashed var(--border);
  opacity:.34; filter:saturate(.25);
  transition:opacity .3s ease, filter .3s ease, border-color .3s ease, background .3s ease;
}
#stage .rl-alt.on{
  opacity:1; filter:none; border-style:solid; border-color:rgba(240,166,74,.55);
  background:rgba(240,166,74,.07);
}
#stage .rl-note.on{
  opacity:1; filter:none; border-style:solid; border-color:rgba(240,166,74,.6);
  background:rgba(240,166,74,.08);
}
#stage .rl-alt-ic, #stage .rl-note-ic{
  width:44px; height:44px; border-radius:13px; flex-shrink:0; font-size:23px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(240,166,74,.12); border:1.5px solid rgba(240,166,74,.3);
}
#stage .rl-alt-n, #stage .rl-note-n{ color:#fff; font-family:var(--font-mono); font-size:21px; font-weight:700; white-space:nowrap; }
#stage .rl-alt-s, #stage .rl-note-s{
  margin-left:auto; color:var(--text-dim); font-family:var(--font-mono);
  font-size:18px; font-weight:600; white-space:nowrap;
}

/* -------------------------------------------------------- relay namespace -- */
#stage .rl-hub{
  height:140px; flex-shrink:0; display:flex; flex-direction:column; gap:14px; justify-content:center;
  padding:16px 20px; border-radius:26px;
  background:radial-gradient(circle at 50% 0%, rgba(58,160,255,.14), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(58,160,255,.5);
  box-shadow:0 0 0 1px rgba(58,160,255,.18), 0 0 60px rgba(58,160,255,.12);
}
#stage .rl-hub-h{ display:flex; align-items:center; gap:14px; }
#stage .rl-hub-ic{
  width:48px; height:48px; border-radius:14px; flex-shrink:0; font-size:25px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.16); border:1.5px solid rgba(58,160,255,.4);
}
#stage .rl-hub-n{
  color:#fff; font-family:var(--font-mono); font-size:21px; font-weight:700;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis; min-width:0;
}
#stage .rl-hub-b{
  margin-left:auto; flex-shrink:0; padding:7px 15px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(58,160,255,.5); background:rgba(58,160,255,.12); color:var(--accent-1);
  font-family:var(--font-mono); font-size:17px; font-weight:700;
}
#stage .rl-hub-f{ display:flex; align-items:center; gap:14px; }
#stage .rl-hc{
  padding:8px 14px; border-radius:10px; white-space:nowrap;
  background:rgba(34,211,238,.14); border:1.5px solid rgba(34,211,238,.45); color:var(--accent-cyan);
  font-family:var(--font-mono); font-size:18px; font-weight:600;
}
#stage .rl-keys{
  margin-left:auto; color:var(--text-dim); font-family:var(--font-mono);
  font-size:18px; font-weight:600; white-space:nowrap; transition:color .3s ease;
}
#stage .rl-keys.hot{ color:var(--accent-1); }

#stage .rl-strip{
  height:72px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:20px;
  background:rgba(20,27,43,.7); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .rl-strip b{
  padding:6px 15px; border-radius:8px; flex-shrink:0;
  background:rgba(58,160,255,.16); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:2px;
}
#stage .rl-strip span{ color:var(--text-primary); font-size:22px; font-weight:600; line-height:1.3; }
#stage .rl-strip.bad{ border-color:rgba(244,74,106,.5); background:rgba(244,74,106,.1); }
#stage .rl-strip.bad b{ background:rgba(244,74,106,.2); color:var(--danger); }
#stage .rl-strip.good{ border-color:rgba(63,185,80,.45); background:rgba(63,185,80,.09); }
#stage .rl-strip.good b{ background:rgba(63,185,80,.2); color:var(--success); }

/* ========================= SCENE 3 · THREE WAYS IN ===================== */
#stage .rl-split{ display:flex; gap:14px; height:100%; }
#stage .rl-col{
  flex:1; min-width:0; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:14px;
  padding:22px 14px; border-radius:26px; text-align:center;
}
#stage .rl-col.vpn, #stage .rl-col.queue{ background:rgba(20,27,43,.6); border:2px solid rgba(58,160,255,.4); }
#stage .rl-col.relay{
  background:radial-gradient(circle at 50% 0%, rgba(34,211,238,.16), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(34,211,238,.6);
  box-shadow:0 0 0 1px rgba(34,211,238,.2), 0 0 60px rgba(34,211,238,.14);
}
#stage .rl-col-h{ font-family:var(--font-mono); font-size:16px; font-weight:800; letter-spacing:1px; white-space:nowrap; }
#stage .rl-col.vpn .rl-col-h, #stage .rl-col.queue .rl-col-h{ color:var(--accent-1); }
#stage .rl-col.relay .rl-col-h{ color:var(--accent-cyan); }
#stage .rl-col-ic{ font-size:50px; line-height:1; }
#stage .rl-col.relay .rl-col-ic{ animation:msd-breathe 2.4s ease-in-out infinite; }
#stage .rl-col-list{ width:100%; display:flex; flex-direction:column; gap:9px; }
#stage .rl-row{
  padding:12px 8px; border-radius:12px;
  background:rgba(14,20,32,.7); border:1.5px solid var(--border); color:var(--text-dim);
  font-size:19px; font-weight:600; line-height:1.25;
}
#stage .rl-row b{ color:var(--text-primary); font-weight:800; }
#stage .rl-col.relay .rl-row b{ color:#fff; }
#stage .rl-col-x{
  width:100%; padding:12px 8px; border-radius:13px;
  background:rgba(58,160,255,.12); border:1.5px solid rgba(58,160,255,.45); color:var(--accent-1);
  font-family:var(--font-mono); font-size:16px; font-weight:700; line-height:1.3;
}
#stage .rl-col-x.hot{ background:rgba(34,211,238,.16); border-color:rgba(34,211,238,.6); color:var(--accent-cyan); }

/* ========================== SCENE 4 · THE PAYOFF ======================= */
#stage .rl-final{
  height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:18px;
  text-align:center;
}
#stage .rl-badge{
  width:132px; height:132px; border-radius:36px; font-size:62px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg, rgba(34,211,238,.28), rgba(58,160,255,.14));
  border:2px solid rgba(34,211,238,.6);
  box-shadow:0 0 0 1px rgba(34,211,238,.3), 0 0 80px rgba(34,211,238,.32);
  animation:msd-breathe 2.4s ease-in-out infinite;
}
#stage .rl-badge-l{ color:var(--accent-cyan); font-family:var(--font-mono); font-size:22px; font-weight:800; letter-spacing:5px; }
#stage .rl-fin-h{ color:#fff; font-size:66px; font-weight:900; line-height:1.12; letter-spacing:-2px; }
#stage .rl-fin-h em{ font-style:normal; color:var(--accent-cyan); }
#stage .rl-fin-row{ display:flex; flex-wrap:wrap; justify-content:center; gap:12px; }
#stage .rl-fin-p{
  padding:12px 20px; border-radius:100px; white-space:nowrap;
  background:rgba(20,27,43,.8); border:1.5px solid rgba(34,211,238,.42); color:var(--text-primary);
  font-size:22px; font-weight:700;
}
#stage .rl-save{
  margin-top:8px; padding:18px 26px; border-radius:20px; max-width:840px;
  background:linear-gradient(90deg, rgba(34,211,238,.2), rgba(58,160,255,.1));
  border:1.5px solid rgba(34,211,238,.55); color:#fff;
  font-size:26px; font-weight:700; line-height:1.35;
}
#stage .rl-save.ping{ animation:msd-punch .4s cubic-bezier(.22,1,.36,1); }

/* ============================== KEYFRAMES ============================== */
@keyframes rl-down{
  0%{ transform:translateY(-26px); opacity:0; }
  30%{ opacity:1; }
  100%{ transform:translateY(22px); opacity:0; }
}
@keyframes rl-up{
  0%{ transform:translateY(26px); opacity:0; }
  30%{ opacity:1; }
  100%{ transform:translateY(-22px); opacity:0; }
}
@keyframes rl-alert{
  0%,100%{ box-shadow:0 0 0 1px rgba(244,74,106,.3), 0 0 40px rgba(244,74,106,.16); }
  50%{ box-shadow:0 0 0 1px rgba(244,74,106,.55), 0 0 80px rgba(244,74,106,.3); }
}
@keyframes rl-whip{
  0%{ transform:translateX(220px) scale(1.04); filter:blur(16px); opacity:0; }
  55%{ filter:blur(3px); opacity:1; }
  100%{ transform:none; filter:blur(0); opacity:1; }
}

