var RL = window.__RL || (window.__RL = {});

MSD.cls('.rl-sc', 'on', false);
MSD.cls('#rl-sc-wall', 'on', true);
MSD.q('#rl-app').textContent = 'orders-api → erp-inventory';
MSD.cls('#rl-lat', 'ok', false);
MSD.cls('#rl-lat', 'bad', false);
MSD.q('#rl-lat-n').textContent = '—';
MSD.cls('#rl-health', 'ok', false);
MSD.cls('#rl-health', 'warn', true);
MSD.q('#rl-health-t').textContent = 'no route';

MSD.cls('#rl-cloud', 'lit', false);
MSD.cls('#rl-cloud', 'bad', false);
MSD.cls('#rl-prem', 'bad', false);
MSD.q('#rl-cloud-b').textContent = 'CALLING';
MSD.cls('#rl-cloud-b', 'hot', false);
MSD.cls('#rl-cloud-b', 'bad', false);
MSD.q('#rl-prem-b').textContent = 'PRIVATE';
MSD.cls('#rl-arrow-in', 'on', false);
MSD.cls('#rl-arrow-in', 'blocked', false);
MSD.cls('#rl-band', 'ok', false);
MSD.q('#rl-band-t').textContent = 'corporate firewall';
MSD.q('#rl-band-b').textContent = 'INBOUND DENY';
MSD.cls('.rl-ask', 'no', false);
MSD.cls('#rl-alt', 'on', false);
MSD.cls('#rl-strip', 'bad', false);
MSD.cls('#rl-strip', 'good', false);
MSD.q('#rl-strip-l').textContent = 'ASK';
MSD.q('#rl-strip-t').textContent = 'The cloud needs one service that lives inside somebody else\'s network.';

MSD.after(500, function(){ MSD.cls('#rl-cloud', 'lit', true); MSD.punch('#rl-cloud', 1); MSD.sfx.blip(1); });
MSD.after(1200, function(){ MSD.cls('#rl-arrow-in', 'on', true); MSD.sfx.blip(2); });
MSD.after(2000, function(){ MSD.punch('#rl-prem', 3); MSD.sfx.blip(3); });

var RL = window.__RL;

MSD.cls('.rl-sc', 'on', false);
MSD.cls('#rl-sc-wall', 'on', true);
MSD.cls('#rl-cloud', 'lit', true);
MSD.cls('#rl-arrow-in', 'on', true);
MSD.cls('#rl-alt', 'on', false);
MSD.cls('#rl-strip', 'good', false);
MSD.q('#rl-strip-l').textContent = 'DENIED';
MSD.q('#rl-strip-t').textContent = 'Every one of these is a ticket with the network team on it.';

MSD.after(300, function(){
  MSD.cls('#rl-arrow-in', 'blocked', true);
  MSD.cls('#rl-cloud', 'lit', false);
  MSD.cls('#rl-cloud', 'bad', true);
  MSD.q('#rl-cloud-b').textContent = 'TIMEOUT';
  MSD.cls('#rl-cloud-b', 'bad', true);
  MSD.cls('#rl-health', 'warn', false);
  MSD.q('#rl-health-t').textContent = 'unreachable';
  MSD.cls('#rl-strip', 'bad', true);
  MSD.shake('#rl-band');
  MSD.sfx.error();
});
MSD.after(1000, function(){ MSD.cls('#rl-ask-1', 'no', true); MSD.sfx.error(); });
MSD.after(1350, function(){ MSD.cls('#rl-ask-2', 'no', true); MSD.sfx.error(); });
MSD.after(1700, function(){ MSD.cls('#rl-ask-3', 'no', true); MSD.sfx.error(); });
MSD.after(2050, function(){ MSD.cls('#rl-ask-4', 'no', true); MSD.sfx.error(); });
MSD.after(2450, function(){
  MSD.q('#rl-strip-l').textContent = 'ALL NO';
  MSD.q('#rl-strip-t').textContent = 'A public door into the datacenter is the one thing nobody will sign off.';
  MSD.shake('#rl-asks');
  MSD.sfx.thud();
